class ProfitMenteBundleEngine{
  constructor(){this.currentJobId=null;this.cancelRequested=false;this._cancelButton=null}
  sanitize(name){return String(name||'asset').replace(/[^a-zA-Z0-9._-]+/g,'_').slice(-120)}
  oct(n,len){return n.toString(8).padStart(len-1,'0')+'\0'}
  header(name,size){const h=new Uint8Array(512),enc=new TextEncoder(),put=(s,o,l)=>h.set(enc.encode(s).slice(0,l),o);put(name,0,100);put('0000777\0',100,8);put('0000000\0',108,8);put('0000000\0',116,8);put(this.oct(size,12),124,12);put(this.oct(Math.floor(Date.now()/1000),12),136,12);for(let i=148;i<156;i++)h[i]=32;h[156]='0'.charCodeAt(0);put('ustar\0',257,6);put('00',263,2);let sum=h.reduce((a,b)=>a+b,0);put(sum.toString(8).padStart(6,'0')+'\0 ',148,8);return h}
  metadata(a,name){const m={id:a.id,name,type:a.type,mime:a.mime||''};for(const k of ['duration','width','height','size','metadataVersion']){const v=Number(a[k]);if(Number.isFinite(v)&&v>=0)m[k]=v}return m}
  async build(project,assets){const enc=new TextEncoder(),parts=[],manifest=structuredClone(project);manifest.version='1.7';manifest.assets=[];for(const a of assets){const filename=`${a.id.slice(0,8)}-${this.sanitize(a.name)}`,path=`assets/${filename}`,bytes=new Uint8Array(await a.blob.arrayBuffer());parts.push(this.header(path,bytes.length),bytes,new Uint8Array((512-bytes.length%512)%512));manifest.assets.push(this.metadata({...a,size:a.size||bytes.length},filename))}const json=enc.encode(JSON.stringify(manifest,null,2));parts.unshift(this.header('project.json',json.length),json,new Uint8Array((512-json.length%512)%512));parts.push(new Uint8Array(1024));return new Blob(parts,{type:'application/x-tar'})}
  async download(project,assets){const blob=await this.build(project,assets),a=document.createElement('a'),safe=this.sanitize(project.name||'profitmente');a.href=URL.createObjectURL(blob);a.download=`${safe}.profitmente.tar`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return blob.size}
  async health(){try{const r=await fetch('/api/health',{cache:'no-store'});if(!r.ok)return {ok:false,render_ready:false};return await r.json()}catch{return {ok:false,render_ready:false}}}
  sleep(ms){return new Promise(r=>setTimeout(r,ms))}
  async errorFrom(r){let msg=`Error HTTP ${r.status}`;try{const data=await r.json();msg=data.error||msg}catch{}return msg}
  ensureCancelButton(onStatus=()=>{}){if(typeof document==='undefined')return null;let b=document.querySelector('#cancelRenderBtn');if(!b){b=document.createElement('button');b.id='cancelRenderBtn';b.textContent='■ Cancelar render';b.title='Cancelar el render MP4 actual';b.hidden=true;const render=document.querySelector('#renderMp4Btn');render?.parentNode?.insertBefore(b,render.nextSibling)}b.onclick=()=>this.cancelLocal(onStatus);this._cancelButton=b;return b}
  setCancelVisible(visible,onStatus=()=>{}){const b=this.ensureCancelButton(onStatus);if(b){b.hidden=!visible;b.disabled=!visible}}
  async cancelLocal(onStatus=()=>{}){const id=this.currentJobId;if(!id)return false;this.cancelRequested=true;onStatus('Cancelando render local…');try{const r=await fetch(`/api/render/jobs/${encodeURIComponent(id)}`,{method:'DELETE'});if(!r.ok&&r.status!==409)throw new Error(await this.errorFrom(r));return true}catch(e){this.cancelRequested=false;onStatus('No se pudo cancelar el render: '+e.message);return false}}
  downloadMp4(mp4,project){if(typeof document==='undefined')return mp4.size;const a=document.createElement('a'),safe=this.sanitize(project.name||'profitmente');a.href=URL.createObjectURL(mp4);a.download=`${safe}.mp4`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);return mp4.size}
  async renderJob(project,blob,onStatus){onStatus(`Enviando ${(blob.size/1048576).toFixed(1)} MB al render local…`);const start=await fetch('/api/render/jobs',{method:'POST',headers:{'Content-Type':'application/x-tar'},body:blob});if(!start.ok)throw new Error(await this.errorFrom(start));const initial=await start.json(),id=initial.job_id;if(!id)throw new Error('El servidor no devolvió un identificador de render.');this.currentJobId=id;this.cancelRequested=false;this.setCancelVisible(true,onStatus);try{let last='';for(let i=0;i<3600;i++){const r=await fetch(`/api/render/jobs/${encodeURIComponent(id)}`,{cache:'no-store'});if(!r.ok)throw new Error(await this.errorFrom(r));const state=await r.json(),status=state.status||'rendering',progress=Math.max(0,Math.min(100,Number(state.progress)||0)),elapsed=Number(state.elapsed)||0;const text=status==='queued'?`Render en cola · ${progress}%`:status==='rendering'?`Renderizando MP4 · ${progress}% · ${elapsed.toFixed(1)}s`:status;if(text!==last){onStatus(text);last=text}if(status==='done'){onStatus('MP4 terminado. Preparando descarga…');const out=await fetch(`/api/render/jobs/${encodeURIComponent(id)}/result`,{cache:'no-store'});if(!out.ok)throw new Error(await this.errorFrom(out));return this.downloadMp4(await out.blob(),project)}if(status==='cancelled')throw new Error('Render cancelado.');if(status==='error')throw new Error(state.error||'El render local falló.');await this.sleep(500)}throw new Error('El render local no terminó dentro del tiempo esperado.')}finally{this.currentJobId=null;this.cancelRequested=false;this.setCancelVisible(false,onStatus)}}
  async renderLegacy(project,blob,onStatus){onStatus(`Enviando ${(blob.size/1048576).toFixed(1)} MB al render local…`);const r=await fetch('/api/render',{method:'POST',headers:{'Content-Type':'application/x-tar'},body:blob});if(!r.ok)throw new Error(await this.errorFrom(r));onStatus('MP4 terminado. Preparando descarga…');return this.downloadMp4(await r.blob(),project)}
  async renderLocal(project,assets,onStatus=()=>{}){const health=await this.health();if(!health.ok)throw new Error('Abre Studio con start_studio_windows.bat para activar el render MP4 directo.');if(!health.render_ready)throw new Error('FFmpeg y FFprobe no están disponibles. Instala FFmpeg gratis y vuelve a abrir Studio.');onStatus('Empaquetando proyecto y medios…');const blob=await this.build(project,assets);return health.render_jobs?this.renderJob(project,blob,onStatus):this.renderLegacy(project,blob,onStatus)}
  readString(bytes,start,len){return new TextDecoder().decode(bytes.slice(start,start+len)).replace(/\0.*$/s,'').trim()}
  async parse(blob){const bytes=new Uint8Array(await blob.arrayBuffer()),files=new Map();let offset=0;while(offset+512<=bytes.length){const header=bytes.slice(offset,offset+512);if(header.every(x=>x===0))break;const name=this.readString(header,0,100),sizeRaw=this.readString(header,124,12),size=parseInt(sizeRaw||'0',8);if(!name||!Number.isFinite(size)||size<0)throw new Error('Paquete TAR inválido');offset+=512;if(offset+size>bytes.length)throw new Error('Paquete TAR truncado');files.set(name,bytes.slice(offset,offset+size));offset+=Math.ceil(size/512)*512}const projectBytes=files.get('project.json');if(!projectBytes)throw new Error('El paquete no contiene project.json');let project;try{project=JSON.parse(new TextDecoder().decode(projectBytes))}catch{throw new Error('project.json inválido')}if(!Array.isArray(project.clips))throw new Error('Proyecto sin clips válidos');const restored=[];for(const meta of project.assets||[]){const path=`assets/${meta.name}`,data=files.get(path);if(!data)throw new Error(`Medio faltante en paquete: ${meta.name}`);const prefix=`${String(meta.id||'').slice(0,8)}-`,stored=String(meta.name||''),originalName=stored.startsWith(prefix)?stored.slice(prefix.length):stored;const restoredMeta={id:meta.id,name:originalName,type:meta.type,mime:meta.mime||'',blob:new Blob([data],{type:meta.mime||'application/octet-stream'})};for(const k of ['duration','width','height','size','metadataVersion']){const v=Number(meta[k]);if(Number.isFinite(v)&&v>=0)restoredMeta[k]=v}if(!restoredMeta.size)restoredMeta.size=data.length;restored.push(restoredMeta)}project.assets=(project.assets||[]).map(meta=>{const clean={id:meta.id,name:meta.name,type:meta.type,mime:meta.mime||''};for(const k of ['duration','width','height','size','metadataVersion']){const v=Number(meta[k]);if(Number.isFinite(v)&&v>=0)clean[k]=v}return clean});return {project,assets:restored}}
  async showReadiness(){if(typeof document==='undefined')return;let badge=document.querySelector('#renderStatus');if(!badge){badge=document.createElement('span');badge.id='renderStatus';badge.className='badge renderStatus';const mode=document.querySelector('header .badge');(mode||document.querySelector('header b'))?.after(badge)}const button=document.querySelector('#renderMp4Btn'),pack=document.querySelector('#bundleBtn'),state=await this.health();badge.classList.remove('ready','warn','offline');if(state.render_ready){badge.textContent=state.render_jobs?'MP4 listo · progreso':'MP4 listo';badge.classList.add('ready');badge.title=`Render local activo · Python ${state.python||'?'} · FFmpeg + FFprobe detectados`;if(button){button.disabled=false;button.title='Renderizar MP4 final localmente'}}else if(state.ok){badge.textContent='MP4 requiere FFmpeg';badge.classList.add('warn');badge.title='Servidor local activo, pero falta FFmpeg/FFprobe';if(button){button.disabled=true;button.title='Instala FFmpeg gratis y reinicia Studio'}if(pack)pack.title='Exportar paquete para render posterior'}else{badge.textContent='MP4 local inactivo';badge.classList.add('offline');badge.title='Abre Studio con start_studio_windows.bat para habilitar el render directo';if(button){button.disabled=false;button.title='Haz clic para ver cómo activar el render local'}}}
}
window.ProfitMenteBundleEngine=ProfitMenteBundleEngine;
if(typeof document!=='undefined')window.addEventListener('DOMContentLoaded',()=>new ProfitMenteBundleEngine().showReadiness());
if(typeof module!=='undefined')module.exports={ProfitMenteBundleEngine};
